-- Legacy callcenter.db schema (schema only, no data).
-- Generated by running the legacy schema code (dbService, authService.init(), webauthnService migrate,
-- blacklistService, sttCleanerService, sttService, topicAnalyticsService) on an empty database,
-- then dumping sqlite_master. Used by migrate-legacy specs to build a temporary SQLite database.
CREATE TABLE calls (
                id TEXT PRIMARY KEY,
                channel TEXT,
                caller_id TEXT,
                operator TEXT,
                operator_exten TEXT,
                direction TEXT DEFAULT 'inbound',
                status TEXT DEFAULT 'ANSWERED',
                hangup_party TEXT,
                duration INTEGER DEFAULT 0,
                cause TEXT,
                created_at TEXT
            );

CREATE TABLE operator_daily_stats (
                stat_date TEXT,
                operator_id TEXT,
                total_calls INTEGER DEFAULT 0,
                answered INTEGER DEFAULT 0,
                client_hangup INTEGER DEFAULT 0,
                operator_hangup INTEGER DEFAULT 0,
                denied INTEGER DEFAULT 0,
                total_duration_sec INTEGER DEFAULT 0, missed INTEGER DEFAULT 0,
                PRIMARY KEY (stat_date, operator_id)
            );

CREATE TABLE operator_reject_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_time TEXT,
                operator_id TEXT,
                caller_id TEXT,
                channel TEXT
            );

CREATE TABLE agent_3cx_call_logs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_time TEXT,
                operator_id TEXT,
                caller_id TEXT,
                event_type TEXT,
                duration_sec INTEGER DEFAULT 0,
                start_time TEXT,
                end_time TEXT,
                hostname TEXT,
                details TEXT
            );

CREATE TABLE operator_missed_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                event_time TEXT,
                operator_id TEXT,
                caller_id TEXT,
                channel TEXT
            );

CREATE TABLE pending_callbacks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                phone TEXT NOT NULL,
                caller_name TEXT,
                source TEXT NOT NULL, -- 'abandoned' | 'ivr_non_working' | 'manual'
                call_time TEXT NOT NULL,
                attempts_count INTEGER DEFAULT 1,
                today_attempts INTEGER DEFAULT 1,
                status TEXT DEFAULT 'pending', -- 'pending' | 'resolved' | 'dismissed'
                dismissed_at TEXT,
                dismissed_by TEXT,
                notes TEXT,
                created_at TEXT DEFAULT (datetime('now', 'localtime')),
                updated_at TEXT DEFAULT (datetime('now', 'localtime'))
            , outbound_attempts INTEGER DEFAULT 0, last_outbound_time TEXT, last_outbound_operator TEXT, last_outbound_cause TEXT, resolution_type TEXT);

CREATE TABLE client_contacts (
                phone TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                organization TEXT,
                notes TEXT,
                language TEXT DEFAULT '',
                telegram_user_id TEXT DEFAULT '',
                created_at TEXT DEFAULT (datetime('now', 'localtime')),
                updated_at TEXT DEFAULT (datetime('now', 'localtime'))
            );

CREATE TABLE auth_users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                salt TEXT NOT NULL,
                role TEXT DEFAULT 'superuser',
                operator_id TEXT,
                created_at TEXT DEFAULT (datetime('now', 'localtime')),
                updated_at TEXT DEFAULT (datetime('now', 'localtime'))
            , email TEXT, webauthn_user_id TEXT);

CREATE TABLE auth_sessions (
                token TEXT PRIMARY KEY,
                username TEXT NOT NULL,
                ip TEXT,
                user_agent TEXT,
                created_at TEXT DEFAULT (datetime('now', 'localtime')),
                expires_at TEXT NOT NULL
            , passkey_id TEXT);

CREATE TABLE auth_lockouts (
                key TEXT PRIMARY KEY, -- IP yoki username
                failed_count INTEGER DEFAULT 0,
                locked_until TEXT,
                last_attempt TEXT DEFAULT (datetime('now', 'localtime'))
            );

CREATE TABLE system_settings (
                key TEXT PRIMARY KEY,
                value TEXT,
                updated_at TEXT DEFAULT (datetime('now', 'localtime'))
            );

CREATE TABLE auth_password_resets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                username TEXT NOT NULL,
                email TEXT NOT NULL,
                code_hash TEXT NOT NULL,
                attempts INTEGER DEFAULT 0,
                expires_at INTEGER NOT NULL,
                reset_token TEXT,
                used INTEGER DEFAULT 0,
                created_at INTEGER NOT NULL
            );

CREATE TABLE auth_email_verifications (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL,
                email TEXT NOT NULL,
                code_hash TEXT NOT NULL,
                attempts INTEGER DEFAULT 0,
                expires_at INTEGER NOT NULL,
                used INTEGER DEFAULT 0,
                created_at INTEGER NOT NULL
            );

CREATE TABLE auth_passkeys (
        id TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        webauthn_user_id TEXT NOT NULL,
        username TEXT NOT NULL,
        operator_id TEXT,
        public_key BLOB NOT NULL,
        counter INTEGER DEFAULT 0,
        device_type TEXT,
        backed_up INTEGER DEFAULT 0,
        transports TEXT,
        device_name TEXT NOT NULL,
        created_at TEXT DEFAULT (datetime('now', 'localtime')),
        last_used_at TEXT,
        FOREIGN KEY(user_id) REFERENCES auth_users(id) ON DELETE CASCADE
      );

CREATE TABLE blacklist (
                    number TEXT PRIMARY KEY,
                    variants TEXT,
                    note TEXT,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
                );

CREATE TABLE stt_learned_rules (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    raw_word TEXT UNIQUE COLLATE NOCASE,
                    clean_word TEXT NOT NULL,
                    occurrences INTEGER DEFAULT 1,
                    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
                );

CREATE TABLE call_transcriptions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                call_key TEXT UNIQUE,
                recording_file TEXT,
                caller_id TEXT,
                duration_sec REAL,
                transcription TEXT,
                formatted_transcription TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            , topic TEXT, sub_topic TEXT, confidence REAL DEFAULT 0);

CREATE TABLE call_topic_analytics (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                call_id TEXT UNIQUE,
                caller_id TEXT,
                call_date TEXT,
                call_year INTEGER,
                call_month INTEGER,
                call_hour INTEGER DEFAULT 12,
                duration_sec INTEGER DEFAULT 0,
                operator TEXT,
                topic_key TEXT NOT NULL,
                sub_topic TEXT,
                confidence REAL DEFAULT 0.85,
                snippet TEXT,
                source TEXT DEFAULT 'stt',
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            );

CREATE INDEX idx_calls_created_at ON calls (created_at DESC);

CREATE INDEX idx_calls_caller_id ON calls (caller_id);

CREATE INDEX idx_calls_operator_exten ON calls (operator_exten);

CREATE INDEX idx_reject_events_time ON operator_reject_events (event_time);

CREATE INDEX idx_reject_events_op ON operator_reject_events (operator_id);

CREATE INDEX idx_3cx_logs_time ON agent_3cx_call_logs (event_time);

CREATE INDEX idx_3cx_logs_op ON agent_3cx_call_logs (operator_id);

CREATE INDEX idx_3cx_logs_type ON agent_3cx_call_logs (event_type);

CREATE INDEX idx_3cx_logs_op_time ON agent_3cx_call_logs (operator_id, event_time);

CREATE UNIQUE INDEX idx_3cx_unique_call ON agent_3cx_call_logs (operator_id, caller_id, start_time);

CREATE INDEX idx_missed_events_time ON operator_missed_events (event_time);

CREATE INDEX idx_missed_events_op ON operator_missed_events (operator_id);

CREATE INDEX idx_pending_callbacks_phone ON pending_callbacks (phone);

CREATE INDEX idx_pending_callbacks_status ON pending_callbacks (status);

CREATE INDEX idx_pending_callbacks_time ON pending_callbacks (call_time DESC);

CREATE INDEX idx_client_contacts_name ON client_contacts (name);

CREATE INDEX idx_client_contacts_org ON client_contacts (organization);

CREATE INDEX idx_auth_users_username ON auth_users(username);

CREATE INDEX idx_auth_sessions_token ON auth_sessions(token);

CREATE INDEX idx_auth_sessions_expires ON auth_sessions(expires_at);

CREATE INDEX idx_auth_lockouts_key ON auth_lockouts(key);

CREATE INDEX idx_auth_password_resets_user ON auth_password_resets(username);

CREATE INDEX idx_auth_password_resets_token ON auth_password_resets(reset_token);

CREATE INDEX idx_auth_email_verifications_user ON auth_email_verifications(username);

CREATE INDEX idx_auth_users_operator_id ON auth_users(operator_id);

CREATE INDEX idx_auth_users_email ON auth_users(email);

CREATE UNIQUE INDEX idx_users_webauthn_uid ON auth_users(webauthn_user_id);

CREATE INDEX idx_sessions_passkey ON auth_sessions(passkey_id);

CREATE INDEX idx_passkeys_uid ON auth_passkeys(user_id);

CREATE INDEX idx_passkeys_wuid ON auth_passkeys(webauthn_user_id);

CREATE INDEX idx_learned_raw ON stt_learned_rules(raw_word);

CREATE INDEX idx_transcribe_key ON call_transcriptions(call_key);

CREATE INDEX idx_transcribe_rec ON call_transcriptions(recording_file);

CREATE INDEX idx_topic_date ON call_topic_analytics(call_date);

CREATE INDEX idx_topic_ym ON call_topic_analytics(call_year, call_month);

CREATE INDEX idx_topic_key ON call_topic_analytics(topic_key);
